    files["src/frontend/web/scripts/build-nginx.mjs"] = "/** Generate the deploy Nginx config from validated public origins (never secrets). */\nimport { writeFileSync } from \"node:fs\";\nimport { fileURLToPath } from \"node:url\";\n\nfunction origin(value, name, optional = false) {\n  if (optional && !value) return null;\n  if (typeof value !== \"string\" || !value || /[\\u0000-\\u0020\\u007f\"';\\\\]/.test(value))\n    throw Error(name + \" is not a clean URL\");\n  let url;\n  try { url = new URL(value); } catch { throw Error(name + \" must be a valid absolute URL\"); }\n  if (![\"http:\", \"https:\"].includes(url.protocol) || !url.hostname ||\n      url.username || url.password || url.search || url.hash)\n    throw Error(name + \" requires a public HTTP(S) URL without credentials/query/fragment\");\n  const loopback = [\"localhost\", \"127.0.0.1\", \"[::1]\"].includes(url.hostname);\n  const internalCI = process.env.CI === \"true\" && process.env.SF_CSP_INTERNAL_TEST === \"true\" &&\n    [\"api\", \"identity\"].includes(url.hostname);\n  if (url.protocol === \"http:\" && !loopback && !internalCI)\n    throw Error(name + \" requires HTTPS (HTTP restricted to localhost and isolated CI)\");\n  return url.origin;\n}\n\nconst api = origin(process.env.VITE_API_URL || \"http://localhost:8080\", \"VITE_API_URL\");\nconst issuer = origin(process.env.VITE_OIDC_AUTHORITY || \"\", \"VITE_OIDC_AUTHORITY\", true);\nconst configuredOidc = [issuer, process.env.VITE_OIDC_CLIENT_ID || \"\",\n  process.env.VITE_OIDC_AUDIENCE || \"\"].filter(Boolean).length;\nif ((configuredOidc !== 0 && configuredOidc !== 3) ||\n    (configuredOidc === 3 && (!process.env.VITE_OIDC_CLIENT_ID.trim() ||\n      !process.env.VITE_OIDC_AUDIENCE.trim())))\n  throw Error(\"OIDC public configuration is incomplete\");\nconst connections = [...new Set([\"'self'\", api, issuer].filter(Boolean))].join(\" \");\nconst policy = [\n  \"default-src 'none'\", \"base-uri 'none'\", \"object-src 'none'\",\n  \"frame-ancestors 'none'\", \"script-src 'self'\",\n  \"style-src 'self' 'unsafe-inline'\", \"img-src 'self' data:\",\n  \"font-src 'self'\", \"connect-src \" + connections,\n  \"frame-src \" + (issuer || \"'none'\"),\n  \"form-action 'self'\" + (issuer ? \" \" + issuer : \"\"),\n].join(\"; \");\nconst config = [\n  \"server {\", \"  listen 80;\", \"  server_name _;\",\n  \"  root /usr/share/nginx/html;\", \"  index index.html;\",\n  \"  location / { try_files $uri $uri/ /index.html; }\",\n  '  add_header Content-Security-Policy \"' + policy + '\" always;',\n  \"  add_header Cache-Control \\\"no-store\\\" always;\",\n  \"  add_header X-Content-Type-Options nosniff always;\",\n  \"  add_header Referrer-Policy no-referrer always;\",\n  \"  add_header X-Frame-Options DENY always;\",\n  '  add_header Permissions-Policy \"camera=(), microphone=(), geolocation=()\" always;',\n  \"}\", \"\",\n].join(\"\\n\");\nwriteFileSync(fileURLToPath(new URL(\"../nginx.conf\", import.meta.url)), config, { mode: 0o644 });\nconsole.log(\"CSP_NGINX_BUILD_PASS: validated public API and OIDC origins\");\n";
