      '    const { oidcManager } = await import(modulePath);',
      '    const manager = oidcManager();',
      '    const before = await manager.getUser();',
      '    if (!before?.refresh_token) return { hasRefresh: false };',
      '    const after = await manager.signinSilent();',
      '    const stored = await manager.getUser();',
      '    if (!after?.access_token) return { hasRefresh: true, renewed: false };',
      '    const replay = await fetch("http://identity:8999/token", {',
      '      method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },',
      '      body: new URLSearchParams({ grant_type: "refresh_token", client_id: "factory-web",',
      '        refresh_token: before.refresh_token }),',
      '    });',
