      '    return { hasRefresh: true, renewed: true, accessRotated: after.access_token !== before.access_token,',
      '      refreshRotated: Boolean(after.refresh_token) && after.refresh_token !== before.refresh_token,',
      '      stored: stored?.refresh_token === after.refresh_token, replayDenied: replay.status === 400,',
      '      apiAuthorized: result.status === 200 };',
