      'test("revoked OIDC refresh token clears session after real invalid_grant", async ({ page }) => {',
      '  test.skip(process.env.E2E_AUTH_MODE !== "oidc", "Requires isolated OIDC fullstack CI");',
      '  await page.goto("/");',
      '  await page.getByRole("button", { name: "Accedi con OpenID Connect" }).click();',
      '  await expect(page.getByLabel("Titolo elemento")).toBeVisible({ timeout: 8000 });',
      '  const outcome = await page.evaluate(async () => {',
      '    const { oidcManager, renewOidcSession } = await import("/src/oidc.ts");',
      '    const manager = oidcManager();',
      '    const user = await manager.getUser();',
      '    if (!user?.refresh_token) return { consumed: false };',
      '    // Consume the refresh token at the real provider, but do NOT update the client store.',
      '    const spent = await fetch("http://identity:8999/token", {',
      '      method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },',
      '      body: new URLSearchParams({ grant_type: "refresh_token", client_id: "factory-web",',
      '        refresh_token: user.refresh_token }),',
      '    });',
      '    try {',
      '      await renewOidcSession();',
      '      return { consumed: spent.status === 200, refused: false, cleared: false };',
      '    } catch (reason) {',
      '      const code = reason && typeof reason === "object" && "error" in reason ?',
      '        String((reason as { error?: unknown }).error) : "unknown";',
      '      return { consumed: spent.status === 200, refused: code === "invalid_grant",',
      '        cleared: await manager.getUser() === null };',
      '    }',
      '  });',
      '  expect(outcome).toEqual({ consumed: true, refused: true, cleared: true });',
      '  await expect(page.getByLabel("Titolo elemento")).toHaveCount(0);',
      '  await expect(page.getByRole("button", { name: "Accedi con OpenID Connect" })).toBeVisible();',
      '  await expect.poll(() => page.evaluate(() => Object.keys(sessionStorage).filter(k => k.startsWith("oidc.user:")).length)).toBe(0);',
      '  await page.reload();',
      '  await expect(page.getByRole("button", { name: "Accedi con OpenID Connect" })).toBeVisible();',
      '});',
